// Upgrade the existing shell without external dependencies. The complete build is one HTML file.
const originalFresh=fresh,originalPathCard=pathCard;
let clockInterval=null,clockLast=0,recognizer=null,speechTimeout=null,speechStatus='',utteranceRef=null,gestureStart=null;
const SESSION_LENGTH=6,SESSION_PASS=.7,BOSS_PASS=.8;
fresh=function(){return {...originalFresh(),version:2,challenges:{},completedGames:0};};
function safeClone(v){return JSON.parse(JSON.stringify(v));}
function resolveGame(id){if(GAME_BY_ID[id])return GAME_BY_ID[id];if(!id.startsWith('review~'))return null;const [,type,key]=id.split('~'),q=SUBITEMS[key];if(!q||!GAME_TYPES[type]||type===q.originalType)return null;const original=GAMES.find(g=>g.items.some(it=>it.key===key));let reviewQ={...q,answers:q.answers.slice(),key};
 if(original?.type==='swipe'){const valid=q.valid;reviewQ={...q,answers:[valid?q.context:q.why.replace(/\.$/,'')],prompt:'Reescreva a frase corretamente.',context:q.context};}
 if(original?.type==='redpen')reviewQ.prompt=`Corrija o trecho: ${q.context}`;
 if(original?.type==='memory')reviewQ.prompt=`What goes with “${q.context}”?`;
 const g={id,unit:q.unit,level:q.level,type,title:'Outra situação, a mesma habilidade',scope:'review',items:[reviewQ],person:'mia',scene:'Mia trouxe um ponto do seu caderno para uma nova tentativa.',messages:[reviewQ.prompt]};
 // Reading and deduction answers only make sense alongside their source material.
 if(original?.artifact)g.reference={title:original.artifactTitle||'Texto de apoio',text:original.artifact};
 else if(original?.clues)g.reference={title:'Pistas para a investigação',text:original.clues};
 if(type==='dictation'){g.sentence=reviewQ.answers[0];g.items[0]={...reviewQ,prompt:'Ouça e reconstrua a frase.',context:''};}
 if(type==='surgery'){const words=reviewQ.answers[0].split(' '),slot=Math.max(0,Math.floor(words.length/2));g.word=words[slot];g.tokens=words.filter((_,i)=>i!==slot);g.slot=slot;g.items[0]={...reviewQ,prompt:'Recoloque a palavra no lugar certo.',context:''};}
 return g;
}
function errorEntry(q,answer,g){const old=state.errors[q.key];state.errors[q.key]={count:(old?.count||0)+1,answer:String(answer).slice(0,2000),date:dayKey(),type:g.type,rule:q.rule||q.why};}
function migrate(v){const r=fresh();for(const k of ['xp','goal','muted','placement','passes','attempts','bosses','seen','daily','days'])if(v[k]!==undefined)r[k]=safeClone(v[k]);for(const [id,e]of Object.entries(v.errors||{}))if(SUBITEMS[id])r.errors[id]={...e,type:SUBITEMS[id].originalType,rule:SUBITEMS[id].rule};return r;}
validateState=function(v){
 if(v?.version===1)v=migrate(v);
 if(!v||v.version!==2||!integer(v.xp,0,1e9)||![30,60,100,150].includes(v.goal)||typeof v.muted!=='boolean'||!(v.placement===null||integer(v.placement,0,5)))throw Error('Progresso incompatível.');
 const r=fresh();for(const k of ['xp','goal','muted','placement'])r[k]=v[k];
 for(const [k,len,max]of [['passes',18,2],['attempts',18,1e6]]){if(!Array.isArray(v[k])||v[k].length!==len||v[k].some(x=>!integer(x,0,max)))throw Error('Unidades inválidas.');r[k]=v[k].slice();}
 if(!Array.isArray(v.bosses)||v.bosses.length!==6||v.bosses.some(b=>typeof b!=='boolean'))throw Error('Selos inválidos.');r.bosses=v.bosses.slice();
 for(const key of ['days','daily','seen','errors','challenges']){if(!v[key]||typeof v[key]!=='object'||Array.isArray(v[key]))throw Error('Histórico inválido.');}
 for(const [k,n]of Object.entries(v.daily)){if(!validDate(k)||!integer(n,0,1e9))throw Error('XP diário inválido.');r.daily[k]=n;}
 for(const [k,b]of Object.entries(v.days)){if(!validDate(k)||b!==true)throw Error('Sequência inválida.');r.days[k]=true;}
 for(const [k,n]of Object.entries(v.seen)){if((!GAME_BY_ID[k]&&!BY_ID[k])||!integer(n,0,1e6))throw Error('Itens vistos inválidos.');r.seen[k]=n;}
 for(const [k,e]of Object.entries(v.errors)){if(!SUBITEMS[k]||!e||!integer(e.count,1,1e6)||typeof e.answer!=='string'||e.answer.length>2000||!validDate(e.date))throw Error('Caderno inválido.');r.errors[k]={count:e.count,answer:e.answer,date:e.date,type:typeof e.type==='string'?e.type:SUBITEMS[k].originalType,rule:SUBITEMS[k].rule};}
 for(const [k,c]of Object.entries(v.challenges)){if(!validDate(k)||!c||!GAME_BY_ID[c.id]||GAME_BY_ID[c.id].scope!=='unit'||typeof c.done!=='boolean')throw Error('Desafio diário inválido.');r.challenges[k]={id:c.id,done:c.done};}
 r.completedGames=integer(v.completedGames)?v.completedGames:0;
 if(v.active!==null){const a=v.active;if(!a||!['placement','session','boss','review','daily','practice'].includes(a.mode)||!Array.isArray(a.ids)||a.ids.length<1||a.ids.length>18||a.ids.some(id=>typeof id!=='string'||!resolveGame(id))||new Set(a.ids).size!==a.ids.length||!integer(a.i,0,a.ids.length-1)||!integer(a.unit,0,17)||!integer(a.level,0,5)||!integer(a.xp,0,10000)||!integer(a.combo,0,200)||!Array.isArray(a.answers)||a.answers.length!==a.i+(a.feedback?1:0)||!a.mini)throw Error('Sessão inválida.');
  const g=resolveGame(a.ids[a.i]),m=a.mini;if(!integer(m.step,0,g.items.length)||typeof m.draft!=='string'||m.draft.length>2000||!Array.isArray(m.results)||m.results.length>g.items.length||m.results.some(x=>!g.items.some(q=>q.key===x.key)||typeof x.correct!=='boolean'||typeof x.answer!=='string'||x.answer.length>2000)||new Set(m.results.map(x=>x.key)).size!==m.results.length)throw Error('Rodada inválida.');
  if(!Number.isFinite(m.remaining)||m.remaining<0||m.remaining>60000||!integer(m.extraErrors,0,10000)||!integer(m.peak,0,200)||!integer(m.streak,0,200))throw Error('Relógio inválido.');
  if(!Array.isArray(m.deck)||m.deck.some(x=>!integer(x,0,(g.pairs?.length||1)*2-1))||!Array.isArray(m.flipped)||m.flipped.length>2||m.flipped.some(x=>!m.deck.includes(x))||!Array.isArray(m.matched)||m.matched.some(x=>!integer(x,0,(g.pairs?.length||1)-1)))throw Error('Cartas inválidas.');
  if(g.type==='memory'&&(m.deck.length!==g.pairs.length*2||new Set(m.deck).size!==m.deck.length))throw Error('Baralho incompleto.');
  if(m.target!==null&&!integer(m.target,0,g.items.length-1))throw Error('Trecho inválido.');if(m.slot!==null&&!integer(m.slot,0,g.tokens?.length??0))throw Error('Posição inválida.');
  if(m.feedback!==null&&(!m.feedback||typeof m.feedback.correct!=='boolean'||typeof m.feedback.answer!=='string'||typeof m.feedback.why!=='string'||!integer(m.feedback.xp,0,100)))throw Error('Feedback inválido.');
  for(const [i,x]of a.answers.entries())if(!x||x.id!==a.ids[i]||!Number.isFinite(x.ratio)||x.ratio<0||x.ratio>1||!integer(x.xp,0,3000))throw Error('Resultado inconsistente.');
  if(a.feedback&&(!Number.isFinite(a.feedback.ratio)||a.feedback.ratio<0||a.feedback.ratio>1||typeof a.feedback.correct!=='boolean'))throw Error('Resultado inválido.');
  if(a.mode==='session'&&(a.ids.length!==6||a.ids.some(id=>resolveGame(id).unit!==a.unit||resolveGame(id).scope!=='unit')||new Set(a.ids.map(id=>resolveGame(id).type)).size<4))throw Error('Sessão sem variedade.');
  if(a.mode==='boss'&&(a.ids.length!==6||a.ids.some(id=>resolveGame(id).scope!==`boss${a.level}`)))throw Error('Cenário inválido.');
  if(a.mode==='placement'&&(a.level>5||a.ids.length!==(a.level+1)*3||a.ids.some((id,i)=>resolveGame(id).level!==LEVELS[Math.floor(i/3)])))throw Error('Nivelamento inválido.');
  if(a.mode==='daily'&&(a.ids.length!==1||!validDate(a.day)||r.challenges[a.day]?.id!==a.ids[0]||r.challenges[a.day].done))throw Error('Desafio diário inconsistente.');
  r.active={mode:a.mode,unit:a.unit,level:a.level,ids:a.ids.slice(),i:a.i,xp:a.xp,combo:a.combo,answers:a.answers.map(x=>({id:x.id,ratio:x.ratio,xp:x.xp})),feedback:a.feedback?safeClone(a.feedback):null,day:a.day||dayKey(),mini:{...safeClone(m),running:false},correct:a.answers.filter(x=>x.ratio>=.7).length,score:a.answers.reduce((n,x)=>n+x.ratio,0)};
 }
 // A result screen is not required to resume progress; discard untrusted presentation data on import.
 r.lastResult=null;return r;
};
load=function(){try{const raw=localStorage.getItem(STORAGE_KEY),loaded=raw?validateState(JSON.parse(raw)):fresh();storageOK=true;loadFailed=false;return loaded;}catch{storageOK=false;loadFailed=true;return fresh();}};
encodeProgress=function(){const bytes=new TextEncoder().encode(JSON.stringify(state));let str='';for(const b of bytes)str+=String.fromCharCode(b);return 'FLUENT2.'+btoa(str);};
decodeProgress=function(raw){if(raw.length>2e6)throw Error('Código muito grande.');const code=raw.trim().replace(/\s/g,'');if(!/^FLUENT[12]\./.test(code))throw Error('Cole um código FLUENT1 ou FLUENT2 completo.');try{return validateState(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(code.slice(8)),c=>c.charCodeAt(0)))));}catch{throw Error('Código inválido ou incompleto. O progresso atual foi preservado.');}};
function currentGame(){return state.active?resolveGame(state.active.ids[state.active.i]):null;}
function currentItem(){const a=state.active,g=currentGame();if(!a||!g)return null;return g.items[g.type==='redpen'?(a.mini.target??0):Math.min(a.mini.step,g.items.length-1)];}
function gamePercent(){const a=state.active;return a?(a.i+(a.feedback?1:0))/(a.mode==='placement'?18:a.ids.length):0;}
function selectGames(ui,n=6){const pool=shuffle(GAMES.filter(g=>g.scope==='unit'&&g.unit===ui)).sort((a,b)=>(state.seen[a.id]||0)-(state.seen[b.id]||0));const picked=[];for(const g of pool){if(picked.some(p=>p.type===g.type))continue;picked.push(g);if(picked.length===n)break;}return picked.map(g=>g.id);}
placementBlock=function(li){return [`g${li*3}-chat`,`g${li*3+1}-surgery`,`g${li*3+2}-reading`];};
function dailyGame(){const key=dayKey();if(state.challenges[key])return GAME_BY_ID[state.challenges[key].id];const li=nextTask().level,pool=GAMES.filter(g=>g.scope==='unit'&&g.level===LEVELS[li]);let h=2166136261;for(const c of key)h=Math.imul(h^c.charCodeAt(0),16777619);return pool[(h>>>0)%pool.length];}
function reviewIds(){let previous='';return Object.entries(state.errors).sort((a,b)=>b[1].count-a[1].count).slice(0,8).map(([key,e],i)=>{const q=SUBITEMS[key],candidates=q.originalType==='swipe'?['trap','dictation','chat']:['chat','tone','surgery','dictation'];const original=e.type||q.originalType;const type=candidates.find(t=>t!==original&&t!==q.originalType&&t!==previous&&(t!=='surgery'||q.answers[0].split(' ').length>1)&&(!['dictation','surgery'].includes(t)||!['reading','detective','memory','gap'].includes(q.originalType)))||'chat';previous=type;return `review~${type}~${key}`;});}
function stopMedia(){const rec=recognizer;recognizer=null;utteranceRef=null;clearTimeout(speechTimeout);if(rec){try{rec.abort();}catch{}}if('speechSynthesis'in window)window.speechSynthesis.cancel();speechStatus='';}
function pauseClock(){if(clockInterval){clearInterval(clockInterval);clockInterval=null;}if(state.active?.mini){state.active.mini.running=false;save();}}
function cleanupGame(){pauseClock();stopMedia();gestureStart=null;}
start=function(mode,ui=0,li=Math.floor(ui/3),specific=null){
 if(state.active){toast('Retome a atividade salva antes de começar outra.');navigate('exercise');return;}
 let ids=[];if(mode==='placement'){li=0;ui=0;ids=placementBlock(0);}else if(mode==='session'){if(!unitUnlocked(ui)){toast('Conclua a etapa anterior primeiro.');return;}ids=selectGames(ui);}else if(mode==='boss'){if(!unlocked(li)||![0,1,2].every(j=>mastered(li*3+j))){toast('Conclua as três unidades do nível primeiro.');return;}ids=GAMES.filter(g=>g.scope===`boss${li}`).map(g=>g.id);ui=li*3+2;}else if(mode==='review'){ids=reviewIds();if(!ids.length){navigate('review');return;}ui=resolveGame(ids[0]).unit;li=Math.floor(ui/3);}else if(mode==='daily'){if(state.placement===null){toast('Faça o nivelamento antes do desafio diário.');start('placement');return;}if(state.challenges[dayKey()]?.done){toast('Desafio de hoje concluído. Amanhã tem outro.');navigate('daily');return;}const g=dailyGame();ui=g.unit;li=Math.floor(ui/3);ids=[g.id];state.challenges[dayKey()]={id:g.id,done:false};}else{mode='practice';if(specific){const g=GAME_BY_ID[specific];if(!g||g.scope!=='unit'||!unlocked(Math.floor(g.unit/3))){toast('Este minijogo será liberado com o nível.');return;}ids=[g.id];ui=g.unit;li=Math.floor(ui/3);}else{const pool=GAMES.filter(g=>g.scope==='unit'&&g.level===LEVELS[li]);ids=shuffle(pool).filter((g,i,a)=>a.findIndex(x=>x.type===g.type)===i).slice(0,6).map(g=>g.id);}}
 state.active={mode,unit:ui,level:li,ids,i:0,correct:0,score:0,xp:0,combo:0,answers:[],feedback:null,day:dayKey(),mini:null};state.lastResult=null;prepareQuestion();save();navigate('exercise');
};
prepareQuestion=function(){stopMedia();const g=currentGame();state.active.mini={step:0,draft:'',results:[],feedback:null,target:null,slot:null,flipped:[],matched:[],deck:g.type==='memory'?shuffle(Array.from({length:g.pairs.length*2},(_,i)=>i)):[],extraErrors:0,remaining:(g.seconds||0)*1000,running:false,started:false,streak:0,peak:0,revealed:false,fallback:false,activityXP:0};};
nextTask=function(){if(state.active)return {mode:'resume',unit:state.active.unit,level:state.active.level};if(state.placement===null)return {mode:'placement',unit:0,level:0};for(let li=0;li<6;li++){if(!unlocked(li))break;for(let j=0;j<3;j++)if(!mastered(li*3+j))return {mode:'session',unit:li*3+j,level:li};if(!levelComplete(li))return {mode:'boss',unit:li*3+2,level:li};}return {mode:'practice',unit:17,level:5};};
next=function(){const n=nextTask();if(n.mode==='resume')navigate('exercise');else start(n.mode,n.unit,n.level);};
function earn(base){const a=state.active,mult=a.mode==='daily'?2:1,xp=base*mult;a.xp+=xp;a.mini.activityXP+=xp;grantXP(xp);return xp;}
function record(q,correct,answer,{extra=false}={}){const a=state.active,g=currentGame(),m=a.mini;if(!extra&&m.results.some(x=>x.key===q.key))return null;if(['swipe','memory'].includes(g.type))pauseClock();state.days[dayKey()]=true;a.combo=correct?a.combo+1:0;const xp=correct?earn(10+(a.combo>=3?5:0)):0;if(!correct)errorEntry(q,answer,g);else if(state.errors[q.key]){state.errors[q.key].count--;if(state.errors[q.key].count<=0)delete state.errors[q.key];}if(extra)m.extraErrors++;else m.results.push({key:q.key,correct,answer:String(answer).slice(0,2000)});m.feedback={correct,answer:correctAnswer(g,q),why:q.why||q.rule,xp,user:String(answer),extra};save();header();sound(correct?'correct':'wrong');if(correct&&a.combo>=5)confetti(18);return m.feedback;}
function correctAnswer(g,q){if(g.type==='swipe')return q.valid?`Correct: ${q.context}`:`Incorrect. ${q.why}`;if(g.type==='memory')return `${q.context} → ${q.answers[0]}`;return q.answers[0];}
function endActivity(force=false){const a=state.active,g=currentGame(),m=a.mini;if(a.feedback)return;if(force){for(const q of g.items)if(!m.results.some(x=>x.key===q.key))record(q,false,'Tempo encerrado / atividade pulada');}
 const correct=m.results.filter(x=>x.correct).length,ratio=correct/(g.items.length+m.extraErrors);let extra=0;if(g.type==='story'&&ratio===1)extra=20;if(g.type==='swipe')extra=Math.min(20,m.peak*2);if(g.type==='memory'&&ratio===1&&m.remaining>=30000)extra=10;if(extra)earn(extra);
 pauseClock();stopMedia();a.feedback={correct:ratio>=.7,ratio,extra:extra*(a.mode==='daily'?2:1),peak:m.peak,last:m.feedback};a.answers.push({id:g.id,ratio,xp:m.activityXP});a.score+=ratio;a.correct+=Number(ratio>=.7);state.seen[g.id]=(state.seen[g.id]||0)+1;if(g.scope==='review')delete state.seen[g.id];state.completedGames++;save();renderExercise();header();
}
getAnswer=function(){return $('#answer')?.value||state.active?.mini.draft||'';};
updateSubmit=function(){const a=state.active;if(!a||a.feedback)return;const g=currentGame(),m=a.mini,b=$('[data-action="submit"]');if(b)b.disabled=m.feedback?false:g.type==='surgery'?m.slot===null:!getAnswer().trim();};
submit=function(skip=false){const a=state.active;if(!a||a.feedback)return;const g=currentGame(),m=a.mini;if(m.feedback){advance();return;}if(skip){endActivity(true);return;}if(['memory','swipe','story'].includes(g.type))return;if(g.type==='redpen'&&m.target===null){toast('Toque em um trecho que precisa de correção.');return;}const q=currentItem();let answer=getAnswer().trim();if(g.type==='surgery'){if(m.slot===null)return;const words=g.tokens.slice();words.splice(m.slot,0,g.word);answer=words.join(' ');}if(!answer)return;m.draft=answer;const correct=checkAnswer(q,answer);record(q,correct,answer);if(g.type==='redpen'){if(m.results.length===g.items.length)endActivity();else renderExercise();}else if(g.items.length===1)endActivity();else renderExercise();};
advance=function(){const a=state.active;if(!a)return;const g=currentGame(),m=a.mini;if(!a.feedback){if(!m.feedback)return;const extra=m.feedback.extra;m.feedback=null;m.draft='';if(g.type==='redpen')m.target=null;else if(g.type==='memory')m.flipped=[];else if(!extra)m.step++;save();if(['swipe','memory'].includes(g.type))startClock();else renderExercise();return;}
 if(a.mode==='placement'&&(a.i+1)%3===0){const passed=a.answers.slice(-3).filter(x=>x.ratio>=.7).length;if(passed<2||a.level===4){finish(passed>=2?a.level+1:a.level);return;}a.level++;a.unit=a.level*3;a.ids.push(...placementBlock(a.level));}
 if(a.i===a.ids.length-1){finish();return;}cleanupGame();a.i++;a.feedback=null;prepareQuestion();save();renderExercise();};
finish=function(placementLevel){const a=state.active;if(!a)return;cleanupGame();const ratio=a.score/a.ids.length;let passed=ratio>=.7,first=false;if(a.mode==='placement'){state.placement=placementLevel;for(let i=0;i<placementLevel*3;i++)state.passes[i]=2;selectedLevel=placementLevel;passed=true;}else if(a.mode==='session'){state.attempts[a.unit]++;if(passed)state.passes[a.unit]=Math.min(2,state.passes[a.unit]+1);}else if(a.mode==='boss'){passed=ratio>=BOSS_PASS;first=passed&&!state.bosses[a.level];if(first){state.bosses[a.level]=true;grantXP(50);a.xp+=50;selectedLevel=Math.min(5,a.level+1);}}else if(a.mode==='daily')state.challenges[a.day]={id:a.ids[0],done:true};
 state.lastResult={mode:a.mode,ratio,correct:a.correct,total:a.ids.length,xp:a.xp,unit:a.unit,level:placementLevel??a.level,passed,mastered:mastered(a.unit),first,results:a.answers};state.active=null;save();navigate('summary');if(passed){confetti(first?100:55);sound('level');}
};
function startClock(){const a=state.active;if(!a||a.feedback||a.mini.feedback)return;const m=a.mini;if(m.running)return;m.started=true;m.running=true;clockLast=performance.now();clockInterval=setInterval(()=>{if(state.active!==a||a.mini!==m||!m.running)return;if(view!=='exercise'||document.hidden||a.feedback||m.feedback){pauseClock();return;}const now=performance.now();m.remaining=Math.max(0,m.remaining-(now-clockLast));clockLast=now;const el=$('.clock-left');if(el){el.textContent=Math.ceil(m.remaining/1000)+'s';el.classList.toggle('urgent',m.remaining<=10000);}if(m.remaining===0){endActivity(true);return;}save();},200);save();renderExercise();}
function judge(valid){const a=state.active,g=currentGame();if(!a||g.type!=='swipe'||a.feedback||a.mini.feedback||!a.mini.running)return;const m=a.mini,q=g.items[m.step],correct=valid===q.valid;const el=$('#swipe-card');if(el&&!reduceMotion()){const rect=el.getBoundingClientRect(),clone=el.cloneNode(true);clone.removeAttribute('id');clone.className='swipe-card flying-card';Object.assign(clone.style,{left:rect.left+'px',top:rect.top+'px',width:rect.width+'px',height:rect.height+'px',margin:'0'});clone.style.setProperty('--fly',valid?'350px':'-350px');clone.style.setProperty('--rotate',valid?'18deg':'-18deg');document.body.append(clone);setTimeout(()=>clone.remove(),350);}
 m.streak=correct?m.streak+1:0;m.peak=Math.max(m.peak,m.streak);record(q,correct,valid?'Julguei correta':'Julguei incorreta');if(m.results.length===g.items.length)endActivity();else renderExercise();}
function flipCard(id){const a=state.active,g=currentGame(),m=a?.mini;if(!a||g.type!=='memory'||a.feedback||m.feedback||!m.running||m.flipped.includes(id)||m.matched.includes(Math.floor(id/2)))return;m.flipped.push(id);if(m.flipped.length===2){const [one,two]=m.flipped,pair=Math.floor(one/2),correct=pair===Math.floor(two/2);if(correct){m.matched.push(pair);record(g.items[pair],true,g.pairs[pair][1]);if(m.matched.length===g.pairs.length){endActivity();return;}}else record(g.items[pair],false,`${cardText(g,one)} ↔ ${cardText(g,two)}`,{extra:true});}save();renderExercise();}
function cardText(g,id){return g.pairs[Math.floor(id/2)][id%2];}
function pickStory(index){const a=state.active,g=currentGame(),m=a.mini;if(a.feedback||m.feedback)return;const q=g.items[m.step];record(q,index===q.correct,q.options[index]);if(m.results.length===g.items.length)endActivity();else renderExercise();}
function chooseRed(partIndex){const a=state.active,g=currentGame(),m=a.mini;if(a.feedback||m.feedback)return;const part=redTokens(g)[partIndex];if(part.error===undefined){const q=g.items.find(q=>!m.results.some(r=>r.key===q.key))||g.items[0];record(q,false,`Trecho já correto marcado: ${part.text}`,{extra:true});m.feedback.answer=part.text;m.feedback.why=LEVELS.indexOf(g.level)<3?'Este trecho já estava correto. Procure os erros nas formas verbais ou nas expressões do texto.':'This span is already correct. Check the remaining verb forms and fixed expressions.';}else if(!m.results.some(x=>x.key===g.items[part.error].key)){m.target=part.error;m.draft='';}save();renderExercise();}
function redTokens(g){return g.parts.flatMap(p=>p.error!==undefined?[p]:p.text.split(/(\s+)/).filter(Boolean).map(text=>({text,space:/^\s+$/.test(text)})));}
function feedbackBlock(f){if(!f)return '';return `<div class="feedback round-feedback ${f.correct?'':'wrong'}" role="status"><div class="feedback-title">${icon(f.correct?'check':'refresh',f.correct?'check-draw':'')}${f.correct?'É isso.':'Um ajuste aqui.'}${f.xp?`<span style="margin-left:auto">+${f.xp} XP</span>`:''}</div><p class="answer" lang="en">${esc(f.answer)}</p><p>${esc(f.why)}</p></div>`;}
function answerBox(label='Sua resposta em inglês'){const m=state.active.mini;return `<label class="question-label" for="answer">${label}</label><textarea class="question-input" id="answer" rows="2" lang="en" spellcheck="false" autocomplete="off" autocorrect="off" autocapitalize="none" enterkeyhint="done" maxlength="2000" placeholder="Escreva aqui…" ${m.feedback||state.active.feedback?'disabled':''}>${esc(m.draft)}</textarea>`;}
function chatHeader(person){const c=CAST[person]||CAST.mia;return `<div class="chat-header"><div class="character" style="--cast:${c.color}">${c.initials}</div><div><strong>${c.name}</strong><small>${c.role}</small></div><span class="chat-companion"><img src="assets/papagaio-azul.png" alt="Papagaio Azul, seu parceiro de conversa"><span>seu parceiro</span></span><span class="dot" aria-hidden="true"></span></div>`;}
function reaction(g,correct,q){return correct?CAST[g.person||'mia'].good:(q?.bad||CAST[g.person||'mia'].bad);}
function stageHTML(g){const reference=g.reference?`<aside class="artifact"><div class="artifact-head">${icon('book')}${esc(g.reference.title)}</div><div class="artifact-body ticket" lang="en">${esc(g.reference.text)}</div></aside>`:'';return reference+stageBodyHTML(g);}
function stageBodyHTML(g){const a=state.active,m=a.mini,q=currentItem(),blocked=!!m.feedback||!!a.feedback;
 if(g.type==='chat')return `${g.scene?`<p class="scene-label">${esc(g.scene)}</p>`:''}<div class="chat-shell">${chatHeader(g.person)}<div class="chat-body">${g.messages.map(t=>`<div class="bubble" lang="en">${esc(t)}</div>`).join('')}${m.feedback?`<div class="bubble me">${esc(m.feedback.user)}</div><div class="bubble reaction" lang="en">${esc(reaction(g,m.feedback.correct))}</div>`:''}</div></div><h2 class="game-question" id="question-heading">${esc(q.prompt)}</h2>${q.context?`<div class="context">${esc(q.context)}</div>`:''}${answerBox()}`;
 if(g.type==='redpen'){const tokens=redTokens(g);return `<p class="scene-label">Há ${g.items.length} erros escondidos. Toque em um trecho e escreva a correção. Marcar um trecho correto também conta como erro.</p><div class="paper-doc"><header>${esc(g.docTitle)}</header><div class="red-copy" lang="en">${tokens.map((p,i)=>{if(p.space)return p.text;const result=p.error!==undefined?m.results.find(r=>r.key===g.items[p.error].key):null;return `<button class="red-token ${p.error===m.target?'target':''} ${result?'fixed '+(result.correct?'':'bad-fix'):''}" data-red="${i}" ${blocked||result?'disabled':''}>${esc(result?g.items[p.error].answers[0]:p.text)}</button>`;}).join('')}</div></div><div class="score-chips"><span class="score-chip">${m.results.length}/${g.items.length} trechos revisados</span>${m.extraErrors?`<span class="score-chip">${m.extraErrors} marcações indevidas</span>`:''}</div>${m.target!==null&&!m.feedback?`<div class="red-editor"><p class="tiny muted">Trecho selecionado: <strong>${esc(g.items[m.target].context)}</strong></p>${answerBox('Escreva somente a correção do trecho')}</div>`:''}`;}
 if(g.type==='swipe'||g.type==='memory'){if(!m.started)return `<div class="round-start">${icon(g.type==='swipe'?'cards':'grid')}<h2>${g.type==='swipe'?'Confie no seu radar.':'Encontre as conexões.'}</h2><p>${g.type==='swipe'?'Deslize à direita para uma frase correta e à esquerda para uma incorreta. Você também pode usar os botões. São 8 frases em até 45 segundos.':'Vire as cartas e conecte quatro pares em até 60 segundos. Cada combinação errada reduz a precisão.'}</p><button class="btn" data-game="clock">Começar rodada${icon('arrow')}</button></div>`;
 const timer=`<div class="timer-strip"><span>${g.type==='swipe'?`Melhor sequência: ${m.peak} · ${m.results.length}/8 julgamentos`:`${m.matched.length}/4 pares · ${m.extraErrors} tentativas incorretas`}</span><strong class="clock-left">${Math.ceil(m.remaining/1000)}s</strong></div>${!m.running&&!a.feedback?(m.feedback?'<div class="round-pause">Relógio pausado para você ler a explicação. Clique em Continuar quando estiver pronto.</div>':'<div class="round-pause">Relógio pausado. Seu tempo está salvo.<button class="btn secondary" data-game="clock">Retomar</button></div>'):''}`;
 if(g.type==='swipe')return timer+`<div class="swipe-card" id="swipe-card" lang="en">${esc(q.context)}</div>${!blocked?`<div class="judge-controls"><button class="btn wrong" data-judge="false" ${!m.running?'disabled':''}>${icon('close')}Incorreta</button><button class="btn right" data-judge="true" ${!m.running?'disabled':''}>${icon('check')}Correta</button></div><p class="round-key" style="text-align:center;margin-top:12px">← incorreta · correta →</p>`:''}`;
 return timer+`<div class="memory-grid">${m.deck.map((id,i)=>{const pair=Math.floor(id/2),match=m.matched.includes(pair),face=match||m.flipped.includes(id);return `<button class="memory-card ${face?'face-up':'face-down'} ${match?'matched':''}" data-card="${id}" aria-label="${face?esc(cardText(g,id)):'Carta fechada '+(i+1)}" ${blocked||match||!m.running?'disabled':''}>${face?`<span class="mini-pair">${id%2?'CONEXÃO':'EXPRESSÃO'}</span>${esc(cardText(g,id))}`:'••'}</button>`;}).join('')}</div>`;}
 if(g.type==='story')return `<p class="scene-label">Decisão ${m.step+1} de ${g.items.length}. Uma história perfeita vale +20 XP extras.</p><div class="chat-shell">${chatHeader(g.person)}<div class="chat-body">${m.results.slice(0,m.step).map((r,i)=>`<div class="bubble me">${esc(g.items[i].answers[0])}</div>`).join('')}<div class="bubble" lang="en">${esc(q.prompt)}</div>${m.feedback?`<div class="bubble me">${esc(m.feedback.user)}</div><div class="bubble reaction" lang="en">${esc(reaction(g,m.feedback.correct,q))}</div>`:''}</div></div><div class="options">${q.options.map((o,i)=>`<button class="option game-option" data-story="${i}" ${blocked?'disabled':''}><span class="option-key">${i+1}</span>${esc(o)}</button>`).join('')}</div>`;
 if(g.type==='dictation')return `<div class="audio-panel"><div class="wave" id="voice-wave" aria-hidden="true">${[15,25,35,45,30,40,20,32,18].map((h,i)=>`<span style="--h:${h}px;--d:${i*.06}s"></span>`).join('')}</div><div class="button-row"><button class="btn" data-game="listen">${icon('audio')}Ouvir</button><button class="btn secondary" data-game="slow">${icon('clock')}Mais devagar</button></div><p id="speech-status" class="inline-status" role="status">${esc(speechStatus||'A voz depende dos recursos do seu navegador.')}</p></div><button class="text-btn" data-game="fallback">${m.fallback?'Alternativa de leitura ativada':'Sem áudio? Usar alternativa de leitura'}</button>${m.fallback?`<div class="game-note">Modo de leitura e reconstrução: não avalia escuta.<button class="text-btn" data-game="reveal">${m.revealed?'Ocultar e escrever':'Mostrar a mensagem'}</button>${m.revealed?`<p class="spoken-line" lang="en">${esc(g.sentence)}</p>`:''}</div>`:''}${answerBox('Digite a mensagem em inglês')}`;
 if(g.type==='speak')return `<p class="scene-label">${esc(g.scene||'Leia a frase em voz alta.')}</p><div class="spoken-line" lang="en">${esc(g.sentence)}</div><button class="mic-button ${recognizer?'listening':''}" data-game="microphone" aria-label="${recognizer?'Parar gravação':'Começar a falar'}">${icon('mic')}</button><p id="speech-status" class="inline-status" role="status" style="text-align:center">${esc(speechStatus||(window.SpeechRecognition||window.webkitSpeechRecognition?'Toque no microfone para começar.':'Reconhecimento de voz indisponível. Use a alternativa digitada.'))}</p><p class="tiny muted" style="text-align:center">O navegador pode processar áudio online. A conferência usa a transcrição, não avalia pronúncia.</p>${answerBox('Transcrição ou alternativa digitada')}<p class="mini-evidence">Você pode corrigir uma falha da transcrição antes de verificar.</p>`;
 if(g.type==='surgery')return `<p class="scene-label">Uma palavra foi retirada. Arraste-a ou toque no espaço onde ela deve entrar.</p><div style="text-align:center"><span class="surgery-word" id="surgery-word" draggable="true" lang="en">${esc(g.word)}</span></div><div class="surgery-line" lang="en">${Array.from({length:g.tokens.length+1},(_,i)=>`<button class="slot ${m.slot===i?'chosen':''}" data-slot="${i}" aria-pressed="${m.slot===i}" aria-label="Inserir ${esc(g.word)} na posição ${i+1}" ${blocked?'disabled':''}>${m.slot===i?esc(g.word):'+'}</button>${i<g.tokens.length?`<span>${esc(g.tokens[i])}</span>`:''}`).join('')}</div>`;
 if(g.type==='reading')return `<div class="artifact"><div class="artifact-head">${icon('ticket')}${esc(g.artifactTitle)}</div><div class="artifact-body ticket" lang="en">${esc(g.artifact)}</div></div><h2 class="game-question" id="question-heading" lang="en">${esc(q.prompt)}</h2>${answerBox('Responda em inglês; uma resposta curta basta')}`;
 if(g.type==='detective')return `<p class="scene-label">Leia todas as pistas. Sua conclusão precisa caber nos fatos.</p><div class="clue-board" lang="en">${esc(g.clues)}</div><div class="suspects">${g.suspects.map(n=>`<span class="suspect">${icon('search')}${n}</span>`).join('')}</div><h2 class="game-question" id="question-heading" lang="en">${esc(q.prompt)}</h2>${answerBox('Quem é? Escreva o nome em inglês')}`;
 if(g.type==='tone')return `<div class="tone-context"><div class="tone-tag">MENSAGEM ORIGINAL</div>${icon('arrow')}<div class="tone-tag new">SUA REFORMULAÇÃO</div></div>${q.context?`<div class="context" lang="en">${esc(q.context)}</div>`:''}<h2 class="game-question" id="question-heading">${esc(q.prompt)}</h2>${answerBox()}`;
 return `<span class="pill">Radar brasileiro · traduções que enganam</span><div class="context" lang="en">${esc(q.context||q.prompt)}</div><h2 class="game-question" id="question-heading">${esc(q.prompt)}</h2>${answerBox()}`;
}
renderExercise=function(){const a=state.active;if(!a){navigate('home');return;}const g=currentGame(),m=a.mini,type=GAME_TYPES[g.type],total=a.mode==='placement'?18:a.ids.length;const modeName={placement:'Descoberta do seu nível',session:`${g.level} · ${UNITS[a.unit].title}`,boss:`Boss · ${BOSS_NAMES[a.level]}`,review:'Caderno em outra perspectiva',daily:'Desafio do dia · XP em dobro',practice:'Prática livre'}[a.mode];let feedback=m.feedback?feedbackBlock(m.feedback):'';if(a.feedback)feedback+=`<div class="score-chips"><span class="score-chip">${Math.round(a.feedback.ratio*100)}% nesta atividade</span>${a.feedback.extra?`<span class="score-chip">Bônus: +${a.feedback.extra} XP</span>`:''}${g.type==='swipe'?`<span class="score-chip">Melhor sequência: ${m.peak}</span>`:''}</div>`;
 const canSubmit=['chat','tone','trap','reading','detective','dictation','speak','surgery'].includes(g.type)||(g.type==='redpen'&&m.target!==null);const activeClock=['swipe','memory'].includes(g.type)&&m.started;
 const focused=document.activeElement,focusedControl=focused?.matches?.('button[data-card], button[data-slot]')&&$('#app').contains(focused)?focused:null;
 const focusAttribute=focusedControl?.dataset.card!==undefined?'card':'slot',focusValue=focusedControl?.dataset[focusAttribute];
 const focusSelector=focusValue!==undefined&&/^\d+$/.test(focusValue)?`[data-${focusAttribute}="${focusValue}"]`:null;
 $('#app').innerHTML=`<div class="exercise-wrap"><div class="exercise-top"><button class="icon-btn" data-action="pause" aria-label="Salvar e sair">${icon('close')}</button>${bar(gamePercent(),a.i===total-1&&!!a.feedback,a.i/total)}<span class="tiny muted">${a.i+1}/${total}${a.mode==='placement'?' máx.':''}</span></div><div class="exercise-info"><span>${esc(modeName)}</span><span class="combo ${a.combo>=3?'hot':''}">${a.combo>=3?'COMBO '+a.combo:'+'+a.xp+' XP'}</span></div>${a.mode==='boss'&&a.i===0?`<div class="scene-banner"><strong>${BOSS_NAMES[a.level]}</strong><p>${BOSS_INTROS[a.level]}</p></div>`:''}${a.mode==='session'&&a.i===0?`<aside class="lesson"><h3>UMA IDEIA PARA LEVAR AO JOGO</h3><p>${esc(UNITS[a.unit].lesson)}</p><p class="example" lang="en">${esc(UNITS[a.unit].example)}</p></aside>`:''}<section class="question-card game-stage" id="question-card"><div class="game-label"><span class="type-icon">${icon(type[1])}</span><div><div class="eyebrow" style="color:var(--accent)">${g.level} · ${type[0]}</div><h1 style="font-size:22px;margin:5px 0" tabindex="-1" id="activity-title">${esc(g.title)}</h1></div></div><div style="margin-top:20px">${['dictation','speak'].includes(g.type)?`<div class="audio-companion"><img src="assets/papagaio-azul.png" alt=""><span>${g.type==='dictation'?'Escute no seu ritmo — o papagaio está aqui com você.':'Respire e fale no seu tempo.'}</span></div>`:''}${stageHTML(g)}</div>${feedback}<div class="question-actions">${a.feedback||m.feedback?`<span class="keyboard-hint"><kbd>Enter</kbd> para continuar</span><button class="btn ${(a.feedback?.correct??m.feedback?.correct)?'correct':''}" data-action="advance" id="primary-action">${a.feedback&&a.i===a.ids.length-1&&a.mode!=='placement'?'Ver resultado':'Continuar'}${icon('arrow')}</button>`:`<button class="btn ghost" data-action="skip">Pular</button>${canSubmit?'<span class="keyboard-hint"><kbd>Enter</kbd> para verificar</span><button class="btn" data-action="submit" id="primary-action" disabled>Verificar</button>':activeClock?'<button class="btn ghost" data-game="pause-clock">Pausar rodada</button>':''}`}</div></section><p class="footer-note">${icon('shield')}Seu avanço e o tempo restante ficam salvos.</p></div>`;
 updateSubmit();if(a.feedback||m.feedback)$('#primary-action')?.focus({preventScroll:true});else if(focusSelector){const control=$('#app').querySelector(focusSelector);if(control&&!control.disabled)control.focus({preventScroll:true});}else if($('#answer')&&window.innerWidth>680)$('#answer').focus({preventScroll:true});
};
function speakAudio(slow=false){
 const g=currentGame(),a=state.active;if(!g||g.type!=='dictation')return;
 if(!('speechSynthesis'in window)||!window.SpeechSynthesisUtterance){audioFallback('Voz indisponível. Use a alternativa de leitura.');return;}
 const mini=a.mini;utteranceRef=null;window.speechSynthesis.cancel();clearTimeout(speechTimeout);
 const u=new window.SpeechSynthesisUtterance(g.sentence);utteranceRef=u;
 const isCurrent=()=>state.active===a&&a.mini===mini&&utteranceRef===u&&view==='exercise';
 const voices=window.speechSynthesis.getVoices(),voice=voices.find(v=>/^en[-_]GB/i.test(v.lang))||voices.find(v=>/^en/i.test(v.lang));if(voice)u.voice=voice;u.lang=voice?.lang||'en-US';u.rate=slow?.65:.95;u.pitch=1;
 u.onstart=()=>{if(!isCurrent())return;clearTimeout(speechTimeout);speechStatus='Reproduzindo…';$('#voice-wave')?.classList.add('playing');const s=$('#speech-status');if(s)s.textContent=speechStatus;};
 u.onend=()=>{if(!isCurrent())return;clearTimeout(speechTimeout);speechStatus='Ouça novamente se precisar.';$('#voice-wave')?.classList.remove('playing');const s=$('#speech-status');if(s)s.textContent=speechStatus;};
 u.onerror=e=>{if(isCurrent()&&e.error!=='canceled'&&e.error!=='interrupted')audioFallback('A voz não pôde ser reproduzida. Use a alternativa de leitura.');};
 speechStatus='Preparando a voz…';if($('#speech-status'))$('#speech-status').textContent=speechStatus;
 speechTimeout=setTimeout(()=>{if(isCurrent())audioFallback('A voz não respondeu. A alternativa de leitura está disponível.');},5000);
 try{window.speechSynthesis.speak(u);}catch{if(isCurrent())audioFallback('A voz não está disponível neste navegador.');}
}
function audioFallback(message){if(!state.active)return;clearTimeout(speechTimeout);utteranceRef=null;if('speechSynthesis'in window)window.speechSynthesis.cancel();speechStatus=message;state.active.mini.fallback=true;state.active.mini.revealed=false;save();renderExercise();}
function startRecognition(){
 const active=state.active,mini=active?.mini;if(!active||active.feedback||mini.feedback)return;
 if(recognizer){recognizer.stop();return;}
 const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){speechStatus='Use a alternativa digitada: o navegador não oferece reconhecimento.';renderExercise();return;}
 const rec=new Recognition();recognizer=rec;rec.lang='en-US';rec.interimResults=false;rec.maxAlternatives=1;rec.continuous=false;
 const isCurrent=()=>recognizer===rec&&state.active===active&&active.mini===mini&&view==='exercise'&&!active.feedback&&!mini.feedback;
 rec.onresult=e=>{if(!isCurrent())return;const transcript=e.results[0][0].transcript;mini.draft=transcript;const input=$('#answer');if(input)input.value=transcript;speechStatus='Transcrição pronta. Confira antes de verificar.';if($('#speech-status'))$('#speech-status').textContent=speechStatus;save();updateSubmit();};
 rec.onerror=e=>{if(!isCurrent())return;speechStatus=e.error==='not-allowed'?'Microfone não autorizado. A alternativa digitada continua disponível.':'Não foi possível reconhecer o áudio. Tente de novo ou digite.';};
 rec.onend=()=>{if(!isCurrent())return;recognizer=null;const input=$('#answer');if(input)mini.draft=input.value;renderExercise();};
 speechStatus='Ouvindo…';try{rec.start();renderExercise();}catch{if(!isCurrent())return;recognizer=null;speechStatus='O microfone não pôde iniciar. Use a alternativa digitada.';renderExercise();}
}
const baseHeader=header;
header=function(){baseHeader();const nav=[['home','home','Visão geral'],['path','map','Minha trilha'],['arcade','grid','Minijogos'],['daily','bolt','Desafio diário'],['review','book','Caderno de erros'],['settings','settings','Preferências']];$('#nav').innerHTML=nav.map(([v,i,t])=>`<button data-nav="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${v==='review'&&Object.keys(state.errors).length?`<span class="nav-count">${Object.keys(state.errors).length}</span>`:''}</button>`).join('');$('#crumb').textContent='/ '+(nav.find(n=>n[0]===view)?.[2]||'Em jogo');};
navigate=function(v){if(view==='exercise'&&v!=='exercise')cleanupGame();view=v;header();if(v==='home')renderHome();else if(v==='path')renderPath();else if(v==='review')renderNotebook();else if(v==='settings')renderSettings();else if(v==='exercise')renderExercise();else if(v==='summary')renderSummary();else if(v==='daily')renderDaily();else if(v==='arcade')renderArcade();$('#app').classList.remove('screen-enter');void $('#app').offsetWidth;$('#app').classList.add('screen-enter');window.scrollTo({top:0,behavior:'instant'});};
hero=function(){const n=nextTask(),u=UNITS[n.unit],resume=n.mode==='resume';let title=state.placement===null?'Seu inglês merece<br>uma vida lá fora.':'Menos exercício.<br>Mais experiência.',tag=state.placement===null?'BEM-VINDO AO FLUENT ARCADE':`${u.level} · ${u.title}`,desc=state.placement===null?'Converse, investigue, negocie. Descubra seu nível e aprenda inglês vivendo pequenas histórias.':u.canDo,button=state.placement===null?'Descobrir meu nível':'Jogar minha próxima sessão';if(state.placement!==null)desc=u.canDo;if(resume){tag='SUA HISTÓRIA CONTINUA';title='Tem uma conversa<br>esperando por você.';desc='Sua atividade está salva, incluindo o tempo restante dos jogos.';button='Retomar atividade';}if(n.mode==='boss'){tag='BOSS FIGHT · '+LEVELS[n.level];title=BOSS_NAMES[n.level];desc=BOSS_INTROS[n.level];button='Entrar no cenário';}if(n.mode==='practice'){tag='TRILHA CONCLUÍDA';title='O mundo sempre<br>tem outra conversa.';desc='Continue com situações e nuances de C2.';button='Praticar mais';}return `<section class="hero"><div class="hero-copy"><div class="eyebrow">${esc(tag)}</div><h2>${title}</h2><p>${esc(desc)}</p><button class="btn" data-action="next">${button}${icon('arrow')}</button><div class="tiny muted" style="margin-top:12px">${state.placement===null?'Até 15 atividades · nivelamento adaptativo':'6 minijogos · cerca de 4 minutos'}</div><div class="mini-type-row" aria-label="Chat, detetive, voz, memória">${['chat','search','mic','grid'].map(i=>`<span>${icon(i)}</span>`).join('')}</div></div><div class="hero-art" aria-hidden="true"><div class="mascot-halo"></div><img class="hero-parrot" src="assets/papagaio-azul.png" alt=""><span class="mascot-wave">Oi! <span aria-hidden="true">✦</span></span></div></section>`;};
function challengeCard(){const g=dailyGame(),done=state.challenges[dayKey()]?.done;return `<section class="card daily-challenge"><div class="daily-head"><h3>Uma surpresa por dia.</h3><span class="pill">2× XP</span></div><p>${GAME_TYPES[g.type][0]} · ${g.level}<br>${esc(g.title)}</p>${done?'<span class="daily-completed">Desafio de hoje concluído</span>':'<button class="btn full" data-game="daily">Jogar desafio do dia '+icon('arrow')+'</button>'}<p class="tiny" style="margin:12px 0 0">Um jogo por dia. Sem cobrança para voltar.</p></section>`;}
rail=function(){return `<aside class="stack right-rail">${dailyCard()}${challengeCard()}<section class="card"><div class="daily-head"><h3>Seu passaporte</h3>${icon('shield')}</div><p class="tiny muted" style="margin-top:10px">Um cenário real por nível.</p><div class="stamps">${LEVELS.map((l,i)=>`<span class="stamp ${state.bosses[i]?'earned':''}" title="${BOSS_NAMES[i]}">${l}</span>`).join('')}</div></section></aside>`;};
renderHome=function(){$('#app').innerHTML=intro(state.placement===null?'O inglês acontece jogando.':'Qual história você vai viver hoje?',state.placement===null?'12 formas de praticar. Situações reais. Nenhuma vida para perder.':'Seu próximo passo mistura conversa, descoberta e decisões.','FLUENT ARCADE · INGLÊS EM MOVIMENTO')+`<div class="grid"><div>${hero()}${originalPathCard()}</div>${rail()}</div><div class="footer-note">${icon('shield')}Sem vidas, sem anúncios, sem espera. Progresso salvo no dispositivo.</div>`;};
renderPath=function(){$('#app').innerHTML=intro('Uma trilha. Muitas histórias.','Duas sessões com pelo menos 70% de precisão para dominar cada unidade.','SUA TRILHA CEFR')+`<div class="grid"><div>${originalPathCard()}<p class="new-session-rule">Seis atividades por sessão, pelo menos quatro tipos, sem tipos iguais em sequência. Nos jogos com várias etapas, cada decisão participa da precisão da atividade.</p></div><div class="stack">${challengeCard()}<div class="card"><h3>${BOSS_NAMES[selectedLevel]}</h3><p class="muted tiny" style="margin:12px 0 20px">${BOSS_INTROS[selectedLevel]}</p><button class="btn full" data-action="next">Próximo passo${icon('arrow')}</button></div></div></div>`;};
function renderArcade(){const li=nextTask().level,ui=nextTask().unit;const pool=GAMES.filter(g=>g.scope==='unit'&&g.level===LEVELS[li]);$('#app').innerHTML=intro('Escolha seu jeito de entrar no jogo.','Prática livre: ganha XP e registra erros, sem substituir as sessões da trilha.','12 MINIJOGOS · NENHUMA MESMICE')+`<span class="pill">${LEVELS[li]} · conteúdo do seu nível atual</span><div class="game-grid">${Object.entries(GAME_TYPES).map(([type,[name,ic,desc]])=>{const g=pool.find(g=>g.type===type&&g.unit===ui)||pool.find(g=>g.type===type);return `<button class="game-tile" data-play="${g.id}"><span class="type-icon">${icon(ic)}</span><h3>${name}</h3><p>${desc}</p></button>`;}).join('')}</div>`;}
function renderDaily(){const g=dailyGame(),done=state.challenges[dayKey()]?.done;$('#app').innerHTML=intro('Uma pequena surpresa. Todo dia.','O mesmo desafio durante o dia, com XP dobrado na primeira rodada.','DESAFIO DIÁRIO')+`<div class="summary"><div class="summary-mark">${icon(GAME_TYPES[g.type][1])}</div><span class="pill">${g.level} · ${GAME_TYPES[g.type][0]} · 2× XP</span><h1 style="margin:22px 0 12px">${esc(g.title)}</h1><p>${done?'Você concluiu o desafio de hoje. Continue na trilha ou escolha outro jogo para praticar.':GAME_TYPES[g.type][2]}</p><button class="btn full" ${done?'data-action="next"':'data-game="daily"'}>${done?'Continuar na trilha':'Começar desafio'}</button><button class="btn secondary full" data-nav="arcade">Explorar minijogos</button></div>`;}
renderNotebook=function(){const errors=Object.entries(state.errors).sort((a,b)=>b[1].count-a[1].count);$('#app').innerHTML=intro('Mude o jogo. Resolva o mesmo ponto.','Na revisão, cada erro volta em um tipo de atividade diferente. Um acerto reduz uma ocorrência.','CADERNO DE ERROS')+(errors.length?`<button class="btn" data-action="review">Revisar ${Math.min(8,errors.length)} pontos${icon('arrow')}</button><div class="error-list">${errors.map(([key,e])=>{const q=SUBITEMS[key];return `<article class="card error-card"><div class="error-count">${e.count}×</div><div><span class="eyebrow muted">${q.level} · ${GAME_TYPES[e.type]?.[0]||'Prática anterior'}</span><p style="margin-top:8px">${esc(q.prompt)} ${q.context?`<em>${esc(q.context)}</em>`:''}</p><p class="muted">Sua resposta: ${esc(e.answer)}</p><p class="error-answer">${esc(q.originalType==='swipe'?(q.valid?q.context:q.why):q.answers[0])}</p><p class="muted">${esc(q.rule||q.why)}</p></div></article>`;}).join('')}</div>`:`<div class="card empty">${icon('book')}<h2>Sem pontos pendentes.</h2><p>Quando algo escapar, você encontrará aqui uma nova forma de praticar.</p><button class="btn" data-action="next">Próximo passo${icon('arrow')}</button></div>`);};
renderSummary=function(){const r=state.lastResult;if(!r){navigate('home');return;}let title='Uma história a mais no seu inglês.',desc=`${Math.round(r.ratio*100)}% de precisão nas atividades desta rodada.`;if(r.mode==='placement'){title=`Sua trilha começa no ${LEVELS[r.level]}.`;desc=r.level===5?'Você passou os blocos A1–C1. O C2 fica como próximo ponto de estudo.':'Os níveis anteriores foram marcados como concluídos. Vamos praticar a partir daqui.';}else if(r.mode==='session'){title=r.passed?(r.mastered?'Habilidade dominada. Próxima história?':'Sessão aprovada. A habilidade está crescendo.'):'Você encontrou seus próximos pontos de prática.';desc=r.passed?`${state.passes[r.unit]}/2 sessões aprovadas. ${r.mastered?'Próxima etapa liberada.':'Mais uma sessão com 70% para dominar a unidade.'}`:'O objetivo é 70% de precisão. Seus erros já têm uma nova atividade esperando no caderno.';}else if(r.mode==='boss'){title=r.passed?`Selo ${LEVELS[r.level]} conquistado.`:'Vamos preparar uma segunda tentativa.';desc=r.passed?(r.level===5?'Todos os cenários concluídos. Continue explorando nuance e precisão.':`O cenário foi concluído e o nível ${LEVELS[r.level+1]} está liberado.`):'O boss pede 80% de precisão. Revise os pontos que apareceram e entre no cenário novamente.';}else if(r.mode==='review'){title='Mesmo ponto. Uma nova perspectiva.';desc='Cada acerto reduziu uma ocorrência. Os itens zerados saíram do caderno.';}else if(r.mode==='daily'){title='Desafio do dia concluído.';desc='O XP em dobro já está incluído no total. Amanhã aparece outra situação.';}
 $('#app').innerHTML=`<section class="summary"><div class="summary-mark ${r.mode==='boss'&&r.passed?'boss-seal':''}">${r.mode==='boss'&&r.passed?LEVELS[r.level]:icon(r.passed?'check':'book')}</div><div class="eyebrow muted" style="margin-bottom:13px">${r.mode==='placement'?'NIVELAMENTO CONCLUÍDO':r.mode==='boss'?'CENÁRIO CONCLUÍDO':'RODADA CONCLUÍDA'}</div><h1>${title}</h1><p>${desc}</p><div class="result-grid"><div class="result-box"><b><span id="score-result">0</span>%</b><span>precisão média</span></div><div class="result-box"><b>+<span id="xp-result" style="font:inherit;color:inherit">0</span></b><span>XP conquistados</span></div><div class="result-box"><b>${streak()}</b><span>dias de sequência</span></div></div>${r.first?'<div class="notice">Bônus do primeiro selo: +50 XP incluídos.</div>':''}${r.mode==='placement'?'<div class="notice">Estimativa de entrada na trilha, não certificação CEFR. O nivelamento tem até 15 atividades e não mede todas as habilidades.</div>':''}<div class="history-lines">${r.results.map(x=>{const g=resolveGame(x.id);return `<div class="history-line"><span>${GAME_TYPES[g.type][0]}</span><span>${Math.round(x.ratio*100)}% · +${x.xp} XP</span></div>`;}).join('')}</div><button class="btn full" ${r.mode==='boss'&&!r.passed?'data-action="review"':'data-action="next"'}>${r.mode==='boss'&&!r.passed?'Revisar antes de tentar novamente':'Próximo passo'}${icon('arrow')}</button><button class="btn secondary full" data-nav="path">Ver minha trilha</button></section>`;countTo($('#score-result'),0,Math.round(r.ratio*100));countTo($('#xp-result'),0,r.xp);
};
const previousSettings=renderSettings;
renderSettings=function(){previousSettings();const cards=$('#app').querySelectorAll('.settings>.card');if(cards[2])cards[2].innerHTML=`<h2>Um jogo diferente a cada situação</h2><p>${GAMES.length} atividades originais, 12 tipos de minijogo, 18 unidades e seis bosses com contextos próprios. Cada sessão usa seis tipos diferentes, sem repetições consecutivas. Não há múltipla escolha isolada: as decisões acontecem dentro das histórias.</p><p>Duas sessões com precisão média de 70% dominam uma unidade. Cada etapa de um jogo contribui para sua precisão; marcações indevidas e pares incorretos também contam. No boss, o mínimo é 80%.</p><p>O nivelamento usa chat, cirurgia de frase e leitura: três atividades por nível, até 15 no total. Duas atividades aprovadas avançam o bloco. Passar A1–C1 encaminha ao C2. É uma estimativa de entrada, sem certificação.</p><p>Voz: ditado usa as vozes do navegador. Se não houver áudio, há uma alternativa de leitura e reconstrução. Fala usa SpeechRecognition quando disponível, com alternativa digitada. O reconhecimento pode depender de internet; a conferência usa o texto reconhecido e não mede pronúncia.</p><p>O restante do aplicativo funciona offline. Respostas aceitam contrações, pontuação, caixa e variantes cadastradas; formulações livres não cadastradas podem exigir outra redação.</p><div class="source-links"><a href="https://www.coe.int/en/web/common-european-framework-reference-languages/cefr-descriptors" target="_blank" rel="noopener noreferrer">Council of Europe · Descritores CEFR ↗</a><a href="https://www.englishprofile.org/" target="_blank" rel="noopener noreferrer">English Profile ↗</a><a href="https://developer.mozilla.org/en-US/docs/Web/API/Web_Speech_API/Using_the_Web_Speech_API" target="_blank" rel="noopener noreferrer">Suporte às funções de voz ↗</a></div>`;};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.game){const action=b.dataset.game;if(action==='daily')start('daily');else if(action==='clock')startClock();else if(action==='pause-clock'){pauseClock();renderExercise();}else if(action==='listen'||action==='slow')speakAudio(action==='slow');else if(action==='microphone')startRecognition();else if(action==='fallback'){audioFallback('Alternativa de leitura ativada.');}else if(action==='reveal'&&state.active){state.active.mini.revealed=!state.active.mini.revealed;save();renderExercise();}return;}if(b.dataset.play){const g=GAME_BY_ID[b.dataset.play];if(state.placement===null){toast('Faça o nivelamento primeiro para liberar os minijogos.');next();}else start('practice',g.unit,Math.floor(g.unit/3),g.id);return;}if(!state.active)return;if(b.dataset.judge!==undefined)judge(b.dataset.judge==='true');else if(b.dataset.card!==undefined)flipCard(Number(b.dataset.card));else if(b.dataset.story!==undefined)pickStory(Number(b.dataset.story));else if(b.dataset.red!==undefined)chooseRed(Number(b.dataset.red));else if(b.dataset.slot!==undefined&&!state.active.feedback&&!state.active.mini.feedback){state.active.mini.slot=Number(b.dataset.slot);save();renderExercise();}});
document.addEventListener('input',e=>{if(e.target.id==='answer'&&state.active&&!state.active.feedback){state.active.mini.draft=e.target.value;save();updateSubmit();}});
document.addEventListener('keydown',e=>{if(view==='exercise'&&currentGame()?.type==='swipe'&&!state.active.feedback&&!state.active.mini.feedback){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();judge(e.key==='ArrowRight');}}});
document.addEventListener('pointerdown',e=>{if(e.target.closest('#swipe-card')&&state.active?.mini.running&&!state.active.mini.feedback){gestureStart={x:e.clientX,y:e.clientY,id:e.pointerId};try{e.target.closest('#swipe-card').setPointerCapture(e.pointerId);}catch{}}});
document.addEventListener('pointermove',e=>{const card=$('#swipe-card');if(!gestureStart||!card)return;const dx=e.clientX-gestureStart.x,dy=e.clientY-gestureStart.y;if(Math.abs(dx)>Math.abs(dy)&&!reduceMotion())card.style.transform=`translateX(${dx}px) rotate(${dx/20}deg)`;});
document.addEventListener('pointerup',e=>{if(!gestureStart)return;const dx=e.clientX-gestureStart.x,dy=e.clientY-gestureStart.y;gestureStart=null;const card=$('#swipe-card');if(card)card.style.transform='';if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy))judge(dx>0);});
document.addEventListener('pointercancel',()=>{gestureStart=null;const card=$('#swipe-card');if(card)card.style.transform='';});
document.addEventListener('dragstart',e=>{if(e.target.id==='surgery-word')e.dataTransfer.setData('text/plain','fluent-surgery');});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-slot]'))e.preventDefault();});
document.addEventListener('drop',e=>{const el=e.target.closest('[data-slot]');if(el&&state.active&&!state.active.feedback&&!state.active.mini.feedback){e.preventDefault();if(e.dataTransfer.getData('text/plain')==='fluent-surgery'){state.active.mini.slot=Number(el.dataset.slot);save();renderExercise();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseClock();stopMedia();}else if(view==='exercise'&&state.active)renderExercise();});
window.addEventListener('pagehide',()=>{pauseClock();stopMedia();save();});
// Preserve v1 XP, stamps, mastered units, streaks and error entries. Incomplete v1 sessions restart in the new format.
let wasLegacy=false;try{wasLegacy=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')?.version===1;}catch{}
state=load();selectedLevel=state.placement??0;displayedXP=state.xp;displayedStreak=streak();$('#toast')?.remove();
const sideNote=$('.mini-note');if(sideNote)sideNote.innerHTML='<span class="eyebrow" style="color:var(--accent)">Seu inglês tem uma história.</span><p>4 minutos. 6 minijogos.<br>Uma habilidade de cada vez.</p>';
document.title='Fluent Arcade — Inglês em situações reais';navigate('home');if(wasLegacy){save();toast('Fluent Arcade atualizado. Seu XP, sua trilha e seu caderno foram preservados.');}
